class Solution { public double medianOfSortedArrays(int[] first, int[] second) { if(first.length>second.length)return medianOfSortedArrays(second,first);int m=first.length,n=second.length,lo=0,hi=m;while(lo<=hi){int i=(lo+hi)/2,j=(m+n+1)/2-i;int a=i==0?Integer.MIN_VALUE:first[i-1],b=i==m?Integer.MAX_VALUE:first[i],c=j==0?Integer.MIN_VALUE:second[j-1],d=j==n?Integer.MAX_VALUE:second[j];if(a<=d&&c<=b)return (m+n)%2==1?Math.max(a,c):((long)Math.max(a,c)+Math.min(b,d))/2.0;if(a>d)hi=i-1;else lo=i+1;}return 0.0; } }
